# 단어가 몇 번 나왔는지 사전으로 세기
words = ['고양이', '개', '고양이', '새', '개', '고양이']
count = {}
for w in words:
    if w in count:          # O(1) 확인
        count[w] += 1
    else:
        count[w] = 1
print(count)                # {'고양이': 3, '개': 2, '새': 1}
print(list(count.keys()))   # ['고양이', '개', '새']

# 반 친구 중 두 동아리에 다 든 사람
soccer = {'민수', '지아', '현우'}
chess = {'지아', '현우', '서연'}
print(soccer & chess)       # {'지아', '현우'} (순서는 다를 수 있다)
print(soccer - chess)       # {'민수'}

def grade(score):
    if score >= 90:
        return 'A'
    elif score >= 80:      # 여기 왔으면 이미 90 미만
        return 'B'
    elif score >= 70:
        return 'C'
    else:
        return 'F'

for s in [95, 85, 72, 40]:
    print(s, grade(s))
# 95 A / 85 B / 72 C / 40 F

# if 를 따로 쓰면 여러 개가 다 실행된다
x = 85
if x >= 80:
    print('80 이상')
if x >= 70:
    print('70 이상')   # 이것도 출력된다

