# 1~100 중 3의 배수의 합 — for 와 continue
total = 0
for i in range(1, 101):
    if i % 3 != 0:
        continue          # 3의 배수가 아니면 건너뛰기
    total += i
print(total)              # 1683

# 처음으로 합이 50을 넘는 순간 — while 과 break
s, n = 0, 0
while True:
    n += 1
    s += n
    if s > 50:
        break
print(n, s)               # 10 55

